/* Verifie que toutes les cases du rectangle (x, y, w, h) sont constructibles sur le terrain. */
static inline bool farm_map_terrain_free(int x, int y, int w, int h) {
    if (x < 0 || y < 0 || x + w > FARM_WIDTH || y + h > FARM_HEIGHT) {
        return false;
    }
    for (int dy = 0; dy < h; dy++) {
        for (int dx = 0; dx < w; dx++) {
            if (STANDARD_FARM_GRID[y + dy][x + dx] != TILE_FREE) {
                return false;
            }
        }
    }
    return true;
}

